HEADER_NEW="/** Current thread's scoped construction domain, otherwise the startup-selected\n * process domain. A reference to a scoped value must not outlive that scope;\n * callers retaining the domain beyond their call must copy it. */\nconst lotus::v2::ChainId &GetActiveV2ChainId();\n/** Select the process-wide domain during startup, before concurrent readers.\n * Runtime parameter construction must use ScopedV2ChainId, never this setter. */\nvoid SetActiveV2ChainId(const lotus::v2::ChainId &chain_id);\n\n/** Temporarily override only this thread's chain domain. Own the value rather\n * than borrowing caller storage; worker threads retain the selected process\n * domain unless they independently create an explicit scope. Scopes nest LIFO. */\nclass ScopedV2ChainId final {\npublic:\n    explicit ScopedV2ChainId(const lotus::v2::ChainId &chain_id) noexcept;\n    ~ScopedV2ChainId() noexcept;\n    ScopedV2ChainId(const ScopedV2ChainId &) = delete;\n    ScopedV2ChainId &operator=(const ScopedV2ChainId &) = delete;\n    ScopedV2ChainId(ScopedV2ChainId &&) = delete;\n    ScopedV2ChainId &operator=(ScopedV2ChainId &&) = delete;\n\nprivate:\n    const lotus::v2::ChainId m_chain_id;\n    const lotus::v2::ChainId *const m_previous;\n};"
GLOBAL_OLD='lotus::v2::ChainId g_active_v2_chain_id{};'
GLOBAL_NEW='// Startup-selected process domain, immutable while node worker threads run.\nlotus::v2::ChainId g_active_v2_chain_id{};\n// Explicit temporary construction scopes affect only their calling thread.\nthread_local const lotus::v2::ChainId *g_scoped_v2_chain_id{nullptr};'
GETTER_OLD='const lotus::v2::ChainId &GetActiveV2ChainId() {\n    return g_active_v2_chain_id;\n}'
GETTER_NEW='ScopedV2ChainId::ScopedV2ChainId(const lotus::v2::ChainId &chain_id) noexcept\n    : m_chain_id(chain_id), m_previous(g_scoped_v2_chain_id) {\n    g_scoped_v2_chain_id = &m_chain_id;\n}\n\nScopedV2ChainId::~ScopedV2ChainId() noexcept {\n    assert(g_scoped_v2_chain_id == &m_chain_id);\n    g_scoped_v2_chain_id = m_previous;\n}\n\nconst lotus::v2::ChainId &GetActiveV2ChainId() {\n    return g_scoped_v2_chain_id ? *g_scoped_v2_chain_id : g_active_v2_chain_id;\n}'
KERNEL_OLD="/**\n * Genesis construction hashes the block under the active chain id. Set the id\n * of the network being constructed for the duration, then restore it, so\n * building another network's parameters never changes the selected network.\n */\nclass ScopedV2ChainId {\npublic:\n    explicit ScopedV2ChainId(const lotus::v2::ChainId &chain_id)\n        : m_previous(GetActiveV2ChainId()) {\n        SetActiveV2ChainId(chain_id);\n    }\n    ~ScopedV2ChainId() { SetActiveV2ChainId(m_previous); }\n    ScopedV2ChainId(const ScopedV2ChainId &) = delete;\n    ScopedV2ChainId &operator=(const ScopedV2ChainId &) = delete;\n\nprivate:\n    const lotus::v2::ChainId m_previous;\n};"
TEST_SCOPE_OLD='namespace {\n// Block hashes depend on the process-wide V2 chain id; restore it so later\n// suites keep hashing with the regtest id.\nclass ScopedActiveChainId {\npublic:\n    explicit ScopedActiveChainId(const lotus::v2::ChainId &chain_id)\n        : m_previous(GetActiveV2ChainId()) {\n        SetActiveV2ChainId(chain_id);\n    }\n    ~ScopedActiveChainId() { SetActiveV2ChainId(m_previous); }\n\nprivate:\n    const lotus::v2::ChainId m_previous;\n};\n} // namespace\n\n'
TEST_CASES='namespace {\nCMutableTransaction IdentityDomainFixture(bool fallback) {\n    lotus::v2::Transaction tx;\n    lotus::v2::Input input;\n    input.prev_txid.fill(0x11);\n    input.sequence = CTxIn::SEQUENCE_FINAL;\n    input.flags = 1;\n    input.witnesses.push_back({{0x51}, {}, {}});\n    tx.inputs.push_back(input);\n    lotus::v2::Output output;\n    output.value = 1000;\n    output.branches.push_back(lotus::v2::Hash32{});\n    output.branches[0].fill(0x33);\n    output.paths.push_back({0});\n    // One output exercises InitHashes\' fast path; seventeen use its general\n    // ComputeTransactionIdentities fallback. Neither needs admission/UTXO state.\n    tx.outputs.assign(fallback ? 17 : 1, output);\n    return CMutableTransaction::FromV2Transaction(tx);\n}\n\nbool IdentityMatchesDomain(const CTransaction &tx,\n                           const lotus::v2::ChainId &domain) {\n    lotus::v2::Hash32 id{}, hash{};\n    std::string error;\n    return lotus::v2::ComputeTransactionIdentities(\n               tx.ToV2Transaction(), lotus::v2::DefaultTxProfile, domain,\n               id, hash, error) &&\n           std::equal(id.begin(), id.end(), tx.GetId().begin()) &&\n           std::equal(hash.begin(), hash.end(), tx.GetHash().begin());\n}\n\nbool DecodeIdentityInDomain(const CMutableTransaction &fixture,\n                            const lotus::v2::ChainId &domain) {\n    const auto original = MakeTransactionRef(fixture);\n    const auto wire = EncodeHexTx(*original);\n    CMutableTransaction decoded;\n    if (!DecodeHexTx(decoded, wire)) return false;\n    const auto immutable = MakeTransactionRef(decoded);\n    // The RPC decode path caches identities when mutable bytes become an\n    // immutable transaction. A later domain restoration cannot repair them.\n    if (!IdentityMatchesDomain(*immutable, domain) ||\n        decoded.GetId() != immutable->GetId() ||\n        decoded.GetHash() != immutable->GetHash()) return false;\n    DataStream stream;\n    stream << *immutable;\n    const CTransaction roundtrip(deserialize, stream);\n    return IdentityMatchesDomain(roundtrip, domain) &&\n           EncodeHexTx(roundtrip) == wire;\n}\n} // namespace\n\nBOOST_AUTO_TEST_CASE(scoped_chain_domain_is_owned_nested_and_thread_local) {\n    const auto selected = GetActiveV2ChainId();\n    const auto main = CreateChainParams(ArgsManager{}, ChainType::MAIN);\n    const auto test = CreateChainParams(ArgsManager{}, ChainType::TESTNET);\n    const auto outer_domain = main->V2ChainId() == selected\n                                  ? test->V2ChainId() : main->V2ChainId();\n    const auto inner_domain = outer_domain == main->V2ChainId()\n                                  ? test->V2ChainId() : main->V2ChainId();\n    const std::array fixtures{IdentityDomainFixture(false),\n                              IdentityDomainFixture(true)};\n    {\n        auto borrowed = outer_domain;\n        const ScopedV2ChainId scope(borrowed);\n        borrowed.fill(0x7f); // The scope owns its value.\n        BOOST_CHECK(GetActiveV2ChainId() == outer_domain);\n        // This call must complete while the main-network scope is still held.\n        // A process-global temporary selector leaks that domain into this\n        // unscoped RPC-like reader and gives permanently incorrect cached IDs.\n        auto reader = std::async(std::launch::async, [&] {\n            const bool selected_domain = GetActiveV2ChainId() == selected;\n            const bool fast_identity = DecodeIdentityInDomain(fixtures[0], selected);\n            const bool fallback_identity = DecodeIdentityInDomain(fixtures[1], selected);\n            return selected_domain && fast_identity && fallback_identity;\n        });\n        for (const auto &fixture : fixtures)\n            BOOST_CHECK(DecodeIdentityInDomain(fixture, outer_domain));\n        // Join before nesting changes even the control\'s process domain: the\n        // old implementation fails deterministically, without a raced write.\n        BOOST_CHECK(reader.get());\n        try {\n            const ScopedV2ChainId nested(inner_domain);\n            BOOST_CHECK(GetActiveV2ChainId() == inner_domain);\n            for (const auto &fixture : fixtures)\n                BOOST_CHECK(DecodeIdentityInDomain(fixture, inner_domain));\n            throw std::runtime_error("restore nested construction domain");\n        } catch (const std::runtime_error &) {\n        }\n        BOOST_CHECK(GetActiveV2ChainId() == outer_domain);\n    }\n    BOOST_CHECK(GetActiveV2ChainId() == selected);\n}\n\nBOOST_AUTO_TEST_CASE(parallel_chain_factories_preserve_selected_rpc_identity) {\n    const auto selected = GetActiveV2ChainId();\n    const std::array types{ChainType::MAIN, ChainType::TESTNET, ChainType::REGTEST};\n    std::array<BlockHash, 3> genesis_ids;\n    for (size_t i = 0; i < types.size(); ++i)\n        genesis_ids[i] = CreateChainParams(ArgsManager{}, types[i])\n                             ->GetConsensus().hashGenesisBlock;\n    const std::array fixtures{IdentityDomainFixture(false),\n                              IdentityDomainFixture(true)};\n    std::vector<std::future<bool>> workers;\n    for (size_t i = 0; i < types.size(); ++i) {\n        workers.push_back(std::async(std::launch::async, [&, i] {\n            for (unsigned iteration = 0; iteration < 12; ++iteration) {\n                const auto params = CreateChainParams(ArgsManager{}, types[i]);\n                if (params->GetConsensus().hashGenesisBlock != genesis_ids[i] ||\n                    GetActiveV2ChainId() != selected) return false;\n                for (const auto &tx : params->GenesisBlock().vtx) {\n                    if (tx->nVersion == 7 &&\n                        !IdentityMatchesDomain(*tx, params->V2ChainId()))\n                        return false;\n                }\n                {\n                    const ScopedV2ChainId scope(params->V2ChainId());\n                    if (params->GenesisBlock().GetHash() != genesis_ids[i])\n                        return false;\n                    for (const auto &fixture : fixtures)\n                        if (!DecodeIdentityInDomain(fixture, params->V2ChainId()))\n                            return false;\n                }\n                if (GetActiveV2ChainId() != selected) return false;\n            }\n            return true;\n        }));\n    }\n    workers.push_back(std::async(std::launch::async, [&] {\n        for (unsigned iteration = 0; iteration < 36; ++iteration) {\n            if (GetActiveV2ChainId() != selected) return false;\n            for (const auto &fixture : fixtures)\n                if (!DecodeIdentityInDomain(fixture, selected)) return false;\n        }\n        return true;\n    }));\n    // Drain every owned task before fixtures/expectations leave scope. Worker\n    // callbacks return owned verdicts; Boost assertions stay on this thread.\n    for (auto &worker : workers) BOOST_CHECK(worker.get());\n    BOOST_CHECK(GetActiveV2ChainId() == selected);\n}\n'

def transform(files):
    result=dict(files)
    if PATHS[2] not in result:
        return result
    def text(path):
        v=result[path]
        return v.decode() if isinstance(v,bytes) else v
    def put(path,v):
        result[path]=v.encode() if isinstance(result[path],bytes) else v
    kernel=text(PATHS[2])
    if "class ScopedV2ChainId {" not in kernel and "const ScopedV2ChainId scoped_chain_id" not in kernel:
        return result # Runtime factory scope has not been introduced.
    if KERNEL_OLD in kernel:
        put(PATHS[2],kernel.replace(KERNEL_OLD+"\n","",1))
    elif "class ScopedV2ChainId {" in kernel:
        raise ValueError("unrecognized local selector")
    for path,old,new in [(PATHS[0],HEADER_OLD,HEADER_NEW),(PATHS[1],GLOBAL_OLD,GLOBAL_NEW),(PATHS[1],GETTER_OLD,GETTER_NEW)]:
        v=text(path)
        if new in v:
            continue
        if v.count(old)!=1:
            raise ValueError("missing/nonunique anchor "+path)
        put(path,v.replace(old,new,1))
    if PATHS[3] in result:
        v=text(PATHS[3])
        if TEST_SCOPE_OLD in v:
            v=v.replace(TEST_SCOPE_OLD,"",1)
        elif "class ScopedActiveChainId" in v:
            raise ValueError("unrecognized fixture-global selector")
        v=v.replace("const ScopedActiveChainId scoped_chain_id", "const ScopedV2ChainId scoped_chain_id")
        if '#include <core_io.h>\n' not in v:
            v=v.replace('#include <chainparams.h>\n','#include <chainparams.h>\n#include <core_io.h>\n',1)
        headers='#include <algorithm>\n#include <future>\n#include <stdexcept>\n'
        if headers not in v:
            anchor='#include <boost/test/unit_test.hpp>\n'
            if v.count(anchor)!=1:raise ValueError("test include anchor")
            v=v.replace(anchor,anchor+'\n'+headers,1)
        if 'scoped_chain_domain_is_owned_nested_and_thread_local' in v:
            if TEST_CASES not in v:raise ValueError("partial domain regression")
        else:
            marker='BOOST_AUTO_TEST_SUITE_END()'
            if v.count(marker)!=1:raise ValueError("test suite marker")
            v=v.replace(marker,'\n'+TEST_CASES+'\n'+marker,1)
        put(PATHS[3],v)
    return result
